        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Allah'ın yolundan sapıtmak için O'na eşler koşmuşlardı. De ki: \"Yaşayın bakalım, hiç şüphesiz varacağınız yer ateş olacaktır"
        }
